import java.util.stream.IntStream;

public class Floor {

    private final List<Room> rooms;
    private final Map<String, Integer> prices;

    // initialization

    public Floor(Number aNumberOfRooms, Map<String, Integer> aPriceList) {
        Floor.assertIsValidNumberOfRooms(aNumberOfRooms);
        Floor.assertIsValidPriceList(aPriceList);

        rooms = Floor.createRooms(aNumberOfRooms.intValue());
        prices = new HashMap<>(aPriceList);
    }

    private static List<Room> createRooms(int aNumberOfRooms) {
        return new ArrayList<>(IntStream.rangeClosed(1, aNumberOfRooms).mapToObj(ix -> new Room()).toList());
    }

    // testing

    public boolean isAvailable() {
        return rooms.stream().allMatch(Room::isAvailable);
    }

    // guests

    public void receiveAtRoom(String aGuestType, int aRoomNumber) {
        roomAt(aRoomNumber).receive(aGuestType);
    }

    public void receiveWithReservationAtRoom(String aGuestType, int aRoomNumber) {
        roomAt(aRoomNumber).receiveWithReservation(aGuestType);
    }

    public void reserveRoom(int aRoomNumber) {
        roomAt(aRoomNumber).reserve();
    }

    private Room roomAt(int aRoomNumber) {
        if (aRoomNumber < 1 || aRoomNumber > rooms.size()) {
            Floor.signalRoomNumberDoesNotExist();
        }
        return rooms.get(aRoomNumber - 1);
    }

    // accounting

    public int totalLosses() {
        return sumOverRooms(room -> room.lossUsingIfAbsentGuestType(prices, Floor::signalUnknownGuestTypeAsProfit));
    }

    public int totalProfits() {
        return sumOverRooms(room -> room.profitUsingIfAbsentGuestType(prices, Floor::signalUnknownGuestTypeAsProfit));
    }

    private int sumOverRooms(ToIntFunction<Room> aRoomAmountBlock) {
        return rooms.stream().mapToInt(aRoomAmountBlock).sum();
    }

    // totals

    public int totalRooms() {
        return rooms.size();
    }

    public int totalRoomsAvailable() {
        return countRoomsThat(Room::isAvailable);
    }

    public int totalRoomsOccupied() {
        return countRoomsThat(Room::isOccupied);
    }

    public int totalRoomsReserved() {
        return countRoomsThat(Room::isReserved);
